# GENERATED by bench/app-async/make-app.R from bench/app/app.R; do not edit.
# Benchmark app for the session load-balancing spike. bench/app-async/app.R
# is generated from this file (see bench/app-async/make-app.R).
#
# Every operation is triggered by one input and answered by one output whose
# value starts with the request id, so a protocol-level client can measure the
# latency of each operation exactly. The process ID and session token are
# shown so that routing is observable in a browser too.
#
# Inputs (each value is "<request id>" or "<request id>:<amount>"):
#   fast    cheap reactive calculation
#   cpu     <amount> work units of single-threaded R arithmetic
#   io      Sys.sleep(<amount> ms), a blocking call that uses no CPU
#   state   increments a session-specific counter
#   up      file upload (fileInput); the output reports its size and md5
# Output dl is a session-specific download.

library(shiny)
# Each app process starts its own daemons, and stops them with the app
mirai::daemons(as.integer(Sys.getenv("BENCH_DAEMONS", "1")))
onStop(function() mirai::daemons(0))

# Work units are fixed amounts of computation, not durations, so that a
# process that shares its CPU does the same work more slowly. One unit is
# about 1 ms on one uncontended core of the benchmark machine; see
# bench/calibrate.R. Numerical libraries are not used, so no hidden threads.
ITERATIONS_PER_UNIT <- as.numeric(Sys.getenv("BENCH_ITERATIONS_PER_UNIT", "8900"))

burn <- compiler::cmpfun(function(units) {
  n <- as.integer(units * ITERATIONS_PER_UNIT)
  s <- 0
  for (i in seq_len(n)) s <- s + (i %% 7L) * 0.5
  s
})

parse_request <- function(value) {
  parts <- strsplit(value, ":", fixed = TRUE)[[1]]
  list(id = parts[[1]], amount = if (length(parts) > 1) as.numeric(parts[[2]]) else 0)
}

answer <- function(id, session, ...) {
  paste(c(id, Sys.getpid(), session$token, ...), collapse = "|")
}

ui <- fluidPage(
  tags$h3("Load-balancing benchmark app"),
  tags$p("Process ", tags$code(Sys.getpid()), ", session ", textOutput("session_id", inline = TRUE)),
  fluidRow(
    column(3, actionButton("b_fast", "Fast"), textOutput("fast_out")),
    column(3, numericInput("cpu_units", "CPU units", 200, min = 1), actionButton("b_cpu", "CPU"), textOutput("cpu_out")),
    column(3, numericInput("io_ms", "Sleep ms", 200, min = 1), actionButton("b_io", "Sleep"), textOutput("io_out")),
    column(3, actionButton("b_state", "Count"), textOutput("state_out"))
  ),
  fluidRow(
    column(6, fileInput("up", "Upload"), textOutput("up_out")),
    column(6, downloadButton("dl", "Download session file"))
  ),
  # The buttons drive the same outputs as a protocol client's inputs do
  tags$script(HTML("
    var n = 0;
    function send(id, amount) {
      n += 1;
      Shiny.setInputValue(id, 'b' + n + (amount === undefined ? '' : ':' + amount), {priority: 'event'});
    }
    $(document).on('click', '#b_fast', function() { send('fast'); });
    $(document).on('click', '#b_cpu', function() { send('cpu', $('#cpu_units').val()); });
    $(document).on('click', '#b_io', function() { send('io', $('#io_ms').val()); });
    $(document).on('click', '#b_state', function() { send('state'); });
  "))
)

server <- function(input, output, session) {
  count <- 0

  output$session_id <- renderText(session$token)

  output$fast_out <- renderText({
    req(input$fast)
    r <- parse_request(input$fast)
    answer(r$id, session, sum(seq_len(1000)))
  })

  # The CPU job runs on a daemon; the session answers other inputs meanwhile
  cpu_task <- ExtendedTask$new(function(id, amount) {
    mirai::mirai(list(id = id, value = burn(amount)), burn = burn, amount = amount, id = id)
  })
  observeEvent(input$cpu, {
    r <- parse_request(input$cpu)
    cpu_task$invoke(r$id, r$amount)
  })
  output$cpu_out <- renderText({
    result <- cpu_task$result()
    answer(result$id, session, result$value)
  })

  output$io_out <- renderText({
    req(input$io)
    r <- parse_request(input$io)
    Sys.sleep(r$amount / 1000)
    answer(r$id, session, r$amount)
  })

  output$state_out <- renderText({
    req(input$state)
    r <- parse_request(input$state)
    count <<- count + 1
    answer(r$id, session, count)
  })

  output$up_out <- renderText({
    req(input$up)
    answer("upload", session, input$up$size, unname(tools::md5sum(input$up$datapath)))
  })

  output$dl <- downloadHandler(
    filename = function() "session.txt",
    content = function(file) writeLines(c(session$token, Sys.getpid(), count), file)
  )

  # A protocol client does not report which outputs are visible
  for (id in c("session_id", "fast_out", "cpu_out", "io_out", "state_out", "up_out", "dl")) {
    outputOptions(output, id, suspendWhenHidden = FALSE)
  }
}

shinyApp(ui, server)
